export const angelGrammar = "The opposite of Hell's surveillance: immaculate. Locked off, perfectly composed, centred, slightly too symmetrical. Wide lenses, everything in focus, beautiful light. It looks like an advert, and that is the joke: the angels have made themselves look tremendous and they are of no use whatsoever. No score, no stings; nothing is remarked upon.";

// First sentences carry the visual identity into the prompt studio. No invented names for unnamed roles.
const cast = [
  ["nina", "Sister Nina Doyle", "Protagonist / St Jude's", "45", "Runs St Jude's, a residential house for people the system gave up on. Self-sufficient, can re-plumb a building, lies fluently to authority; gentle with the genuinely broken, brutal with anyone coasting. Daughter of the absconding rockstar, whom she never knew. The pendant is her mother's, always had it — not found on Deborah's bedside — and is the terminal's tracker. Half-angel and ineligible for sorting: nepotism, not tragedy. Faith is functional; God is her employer and she has views about management. Treats divine instruction as an unreliable supplier. Finds being called a saint ridiculous.", ["Practical", "Stubborn", "Self-sufficient"], "sage", "nina"],
  ["kath", "PC Kath Bridges", "Police / moral justice", "30s", "White British police officer in her thirties. Sincerely believes she was left behind to teach moral justice; cannot remember who said so. Maintains paperwork and cites vanished superiors. Notices the wrong details with total commitment. Mild grievance, never fear or amazement. Thinks Ray is the one who gets carried away.", ["Sincere", "Pedantic", "Aggrieved"], "sand", "kath"],
  ["ray", "PC Ray Okonjo", "Police / moral justice", "30s", "Black British police officer in his thirties. Sincerely believes he was left behind to teach moral justice; cannot remember who said so. Maintains paperwork and cites vanished superiors. Follows the wrong details nowhere. Mild grievance, never fear or amazement. Thinks Kath is the one who gets carried away.", ["Sincere", "Pedantic", "Aggrieved"], "sand", "ray"],
  ["danny", "Danny Crane", "Father / water scavenger", "40", "Forty, olive waxed jacket, canvas satchel, untidy dark hair and stubble. Scavenging for water with his daughter Jodie. Has rules: nothing off anyone still alive. Cannot let her be right because the rules are the last bit of parenting he has. Keeps a laminated rules card. Dry and occupied by logistics, never played for grief.", ["Rule-bound", "Practical", "Protective"], "sage", "danny"],
  ["jodie", "Jodie Crane", "Daughter / water scavenger", "11", "Eleven, short sandy hair, navy hoodie under an oversized olive jacket, backpack and a headlamp on her collar. The headlamp stays off in Number Fourteen. Better at crime than Danny and knows it without cruelty. Sees his rules will get them killed. Her mother was raptured and judged worthy. No pathos performance.", ["Observant", "Resourceful", "Direct"], "sand", "jodie"],
  ["martin", "Martin", "Collector / Max's father", "40s", "Failed musician in a denim jacket correct in 1994, hair long at the back on principle. Four guitars, nothing written in eleven years. Collected the rockstar's belongings at estate sales; won the terminal at auction and has it filed as period junk. Cannot reach his son. Aggrieved rather than grieving. Never learns what the machine is.", ["Possessive", "Aggrieved", "Persistent"], "clay", "martin"],
  ["max", "Max", "Flashbacks / accidental operator", "14", "Fourteen-year-old son of Martin, making a retro poster for his esports team The Raptors. Misspells it RAPTURES, balances moral-criterion bars as graphic design, sets opponents weak. Machine shows ERROR, cut straight to UNDO? (prologue shot 31 cut). Asks to clear past attempts, then minimises the window. Alive, unreachable; flashbacks only. Worried he is in trouble, not wracked with guilt. The series does not laugh at him.", ["Unaware", "Competitive", "Practical"], "sand"],
  ["brenda", "Brenda", "Limbo guide", "50s", "Limbo guide in her fifties, cardigan over robes behind a folding table. Thirty years in post; customer-service warmth. Sincere and bored. Cannot tell the religions apart any more. Has no records on anyone. Talks over the cathedral's four-second reverberation.", ["Sincere", "Bored", "Courteous"], "rose", "brenda"],
  ["gordon", "Gordon", "Limbo guide", "60s", "Limbo guide in his sixties, cardigan over robes behind a folding table. Thirty years in post; customer-service warmth. Sincere and bored. Cannot tell the religions apart any more. Has no records on anyone. Talks over the cathedral's four-second reverberation.", ["Sincere", "Bored", "Courteous"], "rose", "gordon"],
  ["vassago", "Vassago", "Hell / intake manager", "50s", "Hell's intake manager in his fifties, short sleeves and a lanyard. In charge, no idea. More concerned with deflating birthday balloons than the intake collapse. Instantly accepts Tamsin's theory that Heaven stole the damned for its numbers. Investigates entirely the wrong thing.", ["Bureaucratic", "Certain", "Incompetent"], "clay", "vassago"],
  ["reek", "Reek", "Hell / intake", "30s", "Hell intake employee in his thirties. Has no opinions. Works on a grey corporate open-plan floor with a blank target board and deflating birthday balloons. Goes along with the theory that Heaven stole their queue. In the field he does the leaning-in and the demonic voice, then runs out of material and sits on the floor. Still not frightened of anything except wasting time.", ["Compliant", "Uncurious", "Bureaucratic"], "clay", "reek"],
  ["tamsin", "Tamsin", "Hell / intake investigator", "20s", "Keen Hell intake employee in her twenties carrying a folder. Proposes that Heaven stole the damned to improve its numbers. Her idea becomes the working theory immediately. Investigates the wrong thing all season. Starts enjoying being a person. In the field she interviews blanks like a survey, writing down Wales and I can only apologise with equal confidence.", ["Keen", "Sincere", "Mistaken"], "clay", "tamsin"],
  ["pat", "Pat", "Hell / undercover auditor", "70s disguise", "A demon disguised as an old lady in her seventies. Too much rouge, too many doilies, a tin containing only boiled sweets and a husband whose name changes. A cupboard of bottled water she never drinks: not bait, just a demon who doesn't drink sitting on the most valuable thing in the county. Keeps a blank chained under the floor with Malcolm; the apology comes up through the locked door. She is waiting for nothing and the burglars pick her house by chance. Keeps an arrangement going after violence but is frosty as after a parking dispute. Distinct from the woman at Number Fourteen; never substitute that woman's sheet for Pat.", ["Nosy", "Overcommitted", "Businesslike"], "rose", "pat"],
  ["malcolm", "Malcolm", "Hell / undercover auditor", "70s", "Pat's other half in the overcommitted disguise: cardigan, slippers, perfectly ordinary. Comes up out of the cellar under the stairs and turns the key behind him. Washes his hands to the elbow and hangs the tea towel back on its hook, square. Thinks the chained blank will break, cannot accept that there is nothing in him to break, and is quietly furious that it keeps apologising. The blank he and Pat keep under the floor is Graham.", ["Methodical", "Ordinary", "Quietly furious"], "clay", "malcolm"],
  ["field-officer", "Hell's third field officer", "Hell / basement interrogation", "", "A female demon with a blank chained in a cellar. Interrogating him about the missing damned, gets only the apology. Reads it as resistance by the system rather than a man doing what he is told. Has notes and thinks she is close. Surveillance grammar, never moving or close.", ["Certain", "Thorough", "Mistaken"], "clay"],
  ["angel-one", "Hariel", "Heaven / equipment recovery", "40s", "One of the Michael-adjacent recovery pair, in his forties, linen, immaculate. Sent down to recover the absconder's equipment with permissions rather than power. Fronts the pair: dead centre, perfectly composed, entirely unbothered, and has not read the report either. Smug rather than stupid and of no use whatsoever. Named in the episode-three cold open; no further backstory supplied.", ["Smug", "Authorised", "Useless"], "sand"],
  ["angel-two", "Soqed", "Heaven / equipment recovery", "30s", "One of the Michael-adjacent recovery pair, in his thirties, linen, immaculate, always slightly behind Hariel. Has not read the report and admits it. Suggests using a blank because everyone's using them; that is what they're for. Smug rather than stupid and equally useless. Named in the episode-three cold open; no further backstory supplied.", ["Smug", "Authorised", "Useless"], "sand"],
  ["alan", "Alan", "Blank / Nina's passenger", "50s", "A blank in his fifties, fleece and sensible shoes, carrying a bag for life containing another bag. Nina picks him up at a wrong lockup. The apology is not a reliable test. Not automatically the chained man from the basement; no identity link has been supplied.", ["Boring", "Compliant", "Ordinary"], "sage", "alan"],
  ["absconder", "The absconder", "1980 / angel turned rockstar", "", "An angel who steals a terminal to live inside creation in 1980. Edits appearance, charisma, confidence and musical ability to the ceiling, leaves social status at default. Conjures a guitar; writes by entering tempo and key. Pockets the tracker off the machine's casing; in the montage, a flash of him fastening it round a girl's neck as a keepsake. Nina's father. Dies five years later and declines undo with NO. Prologue fix: shot 12 pockets tracker plus flash montage, shot 31 cut straight from ERROR to UNDO?. Appearance and age are not locked.", ["Wilful", "Charismatic", "Decisive"], "clay"],
  ["woman-fourteen", "The Woman — Number Fourteen", "Number Fourteen / house rules", "50s", "Woman in her fifties with grey-brown hair in an untidy bun, rumpled tan housecoat over a floral blouse, and a Tesco bag stuffed with crumpled papers. Mid-sentence when the door opens. Plays her situation as house rules and a complaint to the council. The table set for six is never played. No visible listener. This supporting character is not Pat and is not identified as a blank or demon.", ["Matter-of-fact", "Occupied", "Insistent"], "rose", "crazed-woman"],
  ["rescued-blank", "The rescued blank", "Basement / surveillance window", "", "A man chained in a cellar by Hell's third field officer. Gives the apology, doing what he is told. Rescued by Danny and Jodie; talks about laminate flooring. Hell watches through him, putting the rescuers on its map. Do not assume this is Alan. No name or age supplied.", ["Compliant", "Tedious", "Ordinary"], "sand"],
  ["graham", "Graham", "Blank / payroll", "50s", "A blank in his fifties interviewed by Hell's intake in his own front room. Beige cardigan over a shirt and tie, corduroys, slippers. Perfectly content, hands on knees, facing slightly away from anyone. Answers everything helpfully and is never frightened; the drink is hospitality. Most animated on payroll: the wages, but the deductions as well, statutory and voluntary. Says I can only apologise with no pause at all and apologises for never having made a decision. By the episode-four cold open he is the blank chained under Pat's floor, and his apology comes up through the locked door. Not Alan; whether he is also the blank Danny and Jodie rescue in episode five has not been supplied.", ["Content", "Helpful", "Unfazed"], "sand"],
];

export const characters = cast.map(([key, name, role, age, description, traits, color, sheet]) => ({
  id: characterId(key), name, role, age, description, traits, color, createdAt,
  ...(sheet ? { image: `/images/rapture/sheets/${sheet}.jpg` } : {}),
  relations: [],
}));
const reverse = { Parent: "Child", Child: "Parent", Colleague: "Colleague" };
function link(a, b, kind, note) {
  characters.find(c => c.id === characterId(a)).relations.push({ id: `rapture-link-${a}-${b}`, targetId: characterId(b), kind, note });
  characters.find(c => c.id === characterId(b)).relations.push({ id: `rapture-link-${b}-${a}`, targetId: characterId(a), kind: reverse[kind], note });
}
